                c = math.cos(a)
                s = math.sin(a)
                return Main.Task.Point(self.x * c - self.y * s, self.x * s + self.y * c)

            def norm(self):
                length = self.length()
                if length < self.TOL:
                    return Main.Task.Point(0, 0)
                return self.scale(1.0 / length)

            def scale(self, f):
                return Main.Task.Point(self.x * f, self.y * f)

            def length(self):
                return math.hypot(self.x, self.y)

            def __str__(self):
                return "{:.6f} {:.6f}".format(self.x, self.y)

            def __eq__(self, other):
                if not isinstance(other, Main.Task.Point):
